def classify(folder, filename):
    ascii_name = unicodedata.normalize('NFKD', str(filename or '')).encode('ascii', 'ignore').decode()
    name = re.sub(r'[^A-Z0-9]+', '_', ascii_name.upper()).strip('_')
    for marker, code in (
        ('GUIA_PARCELAMENTO_SN', 'guia_parcelamento_simples'),
        ('EXTRATO_SIMPLES', 'extrato_simples'), ('RECIBO_SIMPLES', 'recibo_simples'),
        ('GUIA_DCTFWEB', 'guia_inss'), ('RECIBO_DCTFWEB', 'recibo_dctfweb'),
        ('DECLARACAO_COMPLETA_DCTFWEB', 'declaracao_dctfweb'), ('DAS_', 'das_simples'),
    ):
        if name.startswith(marker) or marker in name:
            return code
    if folder == 'constitutivos_inscricoes':
        if 'INSCRICAO_ESTADUAL' in name:
            return 'inscricao_estadual'
        if 'INSCRICAO_MUNICIPAL' in name:
            return 'inscricao_municipal'
        if 'CNPJ' in name or 'CARTAO' in name:
            return 'cartao_cnpj'
        return 'documento_constitutivo'
    if folder == 'constitutivos_societario':
        if 'ALTERACAO' in name:
            return 'ultima_alteracao'
        if 'CONTRATO' in name or 'ESTATUTO' in name:
            return 'contrato_social'
        return 'documento_constitutivo'
    if str(folder).startswith('constitutivos_'):
        return 'documento_constitutivo'
    if folder == 'pessoal_folha_pagamento':
        return 'folha_pagamento'
    if folder == 'pessoal_guias':
        if 'FGTS' in name:
            return 'guia_fgts'
        if 'INSS' in name or 'DCTF' in name or 'DARF' in name:
            return 'guia_inss'
        return 'documento_pessoal'
    if folder == 'pessoal_relatorios':
        return 'documento_pessoal'
    if folder == 'fiscal_xml':
        return 'xml_fiscal'
    if folder in ('fiscal_guias', 'fiscal_extratos', 'fiscal_declaracoes'):
        return 'documento_fiscal'
    if folder == 'contabil_balanco_anual':
        return 'balanco_anual'
    if str(folder).startswith('contabil_'):
        return 'documento_contabil'
    if folder == 'financeiro_honorarios_mensais':
        return 'honorario'
    return 'outro'


