    types = {}
    for code, name, category, folder, periodicity in CATALOG:
        item, _ = Tipo.objects.update_or_create(
            codigo=code,
            defaults={
                'nome': name, 'categoria': category, 'folder_key': folder,
                'periodicidade': periodicity, 'visivel_app_padrao': True, 'ativo': True,
            },
        )
        types[code] = item.pk
    for document in Documento.objects.all().iterator(chunk_size=500):
        document.tipo_documento_id = types[classify(document.folder_key, document.nome_arquivo)]
        document.competencia = f'{document.ano}{str(document.mes).zfill(2)}' if document.ano and document.mes else ''
        document.origem = 'migracao'
        document.visivel_no_app = True
        document.status = 'disponivel'
        document.save(update_fields=['tipo_documento', 'competencia', 'origem', 'visivel_no_app', 'status'])


